-- verify after 10 (SELECT only): every option has the pi form, correct answer unchanged
-- generated by scripts/prod-open/sat-pi-patches-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; new problem_versions only; no deletes/overwrites; set composition untouched.

select p.id as problem_id, pv.version_no, pv.quality->'auditFix'->>'patch' as patch, pv.options, pv.correct_index, pv.options->>pv.correct_index as correct_text,
  (select bool_and(o ~ 'π') from jsonb_array_elements_text(pv.options) o) as all_pi
from problems p join problem_versions pv on pv.id = p.published_version_id where p.id = any (array['05fcc748-6621-41c8-871c-a1bd9ac131eb','457a2e9f-02ef-41d4-b1d3-a6f1e6e6d90d','508b24dd-fe8e-43c6-b165-408aac130a64','67cf630d-3d76-4c4f-92a7-d397cdce8eb0','813a21dd-752b-40fb-9027-e85e7dc19812','92fa817c-dbaf-4b0c-abd0-011e93f2cc76','a129f183-7cb5-4697-95fa-ce3215fb9761']::uuid[]) order by 3;
